BEGIN;

DROP TABLE IF EXISTS smartgift_price;
DROP TABLE IF EXISTS smartgift_offer;
DROP TABLE IF EXISTS smartgift_model;
DROP TABLE IF EXISTS smartgift_type;
DROP TABLE IF EXISTS smartgift_export_run;

CREATE TABLE smartgift_export_run (
  run_id        TEXT PRIMARY KEY,
  exported_at   TEXT NOT NULL,
  source_path   TEXT NOT NULL,
  commercial_skus INTEGER NOT NULL,
  offers        INTEGER NOT NULL,
  models        INTEGER NOT NULL
);

CREATE TABLE smartgift_type (
  type_id    TEXT PRIMARY KEY,
  group_id   TEXT,
  name_th    TEXT,
  name_en    TEXT,
  aliases_th JSONB,
  aliases_en JSONB
);

CREATE TABLE smartgift_offer (
  code         TEXT PRIMARY KEY,
  name_th      TEXT,
  name_en      TEXT,
  description  TEXT,
  offer_kind   TEXT,
  status       TEXT,
  branding     TEXT,
  origin       TEXT,
  rmb          NUMERIC(12,2),
  image        TEXT,
  price_tiers  JSONB,
  source_ref   JSONB
);

CREATE TABLE smartgift_model (
  base_signature TEXT PRIMARY KEY,
  display_name   TEXT,
  english_name   TEXT,
  type_id        TEXT,
  group_id       TEXT,
  status         TEXT,
  price_source   TEXT,
  offer_codes    JSONB,
  colors         JSONB,
  price_tiers    JSONB,
  source_ref     JSONB
);

CREATE TABLE smartgift_price (
  id                    INTEGER PRIMARY KEY,
  offer_code            TEXT,
  qty_tier              INTEGER,
  unit_price            NUMERIC(12,2),
  unit_price_with_vat   NUMERIC(12,2),
  price_missing         BOOLEAN NOT NULL,
  price_list_group      TEXT,
  flow_account_code     TEXT,
  flow_account_name     TEXT,
  export_date           TEXT,
  source_ref            JSONB
);



